const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};

// 1. Authenticate Token
const authHeader = headers.authorization || headers.Authorization || '';
let token = '';
if (authHeader.startsWith('Bearer ')) {
  token = authHeader.substring(7).trim();
} else if (body.token) {
  token = body.token;
}

if (!token) {
  return [{ json: { error: true, statusCode: 401, message: 'Unauthorized. Authentication token missing.' } }];
}

let decoded;
try {
  decoded = JSON.parse(Buffer.from(token, 'base64').toString('utf8'));
} catch (e) {
  return [{ json: { error: true, statusCode: 401, message: 'Invalid authentication token.' } }];
}

if (!decoded || !decoded.userId || (decoded.exp && decoded.exp < Math.floor(Date.now() / 1000))) {
  return [{ json: { error: true, statusCode: 401, message: 'Session expired. Please log in again.' } }];
}

// 2. Validate Order Input
const orderDate = (body.orderDate || '').trim();
const productId = parseInt(body.productId, 10);
const destination = (body.destination || '').trim();
const notes = (body.notes || '').trim();
const lots = Array.isArray(body.lots) ? body.lots : [];

if (!orderDate) {
  return [{ json: { error: true, statusCode: 400, message: 'Order Date is mandatory.' } }];
}
if (isNaN(productId) || productId <= 0) {
  return [{ json: { error: true, statusCode: 400, message: 'Valid Product selection is mandatory.' } }];
}
if (!destination) {
  return [{ json: { error: true, statusCode: 400, message: 'Destination / Hospital department is mandatory.' } }];
}
if (lots.length === 0) {
  return [{ json: { error: true, statusCode: 400, message: 'At least one lot is compulsory.' } }];
}

let totalQuantity = 0;
const validatedLots = [];

for (let i = 0; i < lots.length; i++) {
  const lot = lots[i];
  const qty = parseFloat(lot.quantity);
  const unit = (lot.unit || '').trim();
  const calDate = (lot.calibrationDate || '').trim();
  const calTime = (lot.calibrationTime || '').trim();

  if (isNaN(qty) || qty <= 0) {
    return [{ json: { error: true, statusCode: 400, message: `Lot #${i+1}: Quantity must be greater than zero.` } }];
  }
  if (!['mCi', 'Dose'].includes(unit)) {
    return [{ json: { error: true, statusCode: 400, message: `Lot #${i+1}: Unit must be either 'mCi' or 'Dose'.` } }];
  }
  if (!calDate || !calTime) {
    return [{ json: { error: true, statusCode: 400, message: `Lot #${i+1}: Calibration date and time are mandatory.` } }];
  }

  totalQuantity += qty;
  validatedLots.push({
    lotNumber: i + 1,
    quantity: qty,
    unit: unit,
    calibrationDate: calDate,
    calibrationTime: calTime
  });
}

return [{
  json: {
    userId: decoded.userId,
    clientId: decoded.clientId, // STRICT server-side identity: never trust body.clientId
    clientRole: decoded.role,
    hospitalName: decoded.hospitalName,
    orderDate,
    productId,
    destination,
    notes,
    totalLots: validatedLots.length,
    totalQuantity,
    lots: validatedLots
  }
}];

const orderData = $input.first().json;
const lots = $('Verify Token & Validate Lots').first().json.lots;
const orderId = orderData.order_id;
const internalOrderId = orderData.id;

// Generate parameterized multi-row insert for order_lots
const lotInserts = lots.map((lot, idx) => {
  const lotIndexPad = String(lot.lotNumber).padStart(2, '0');
  const uniqueLotId = `${orderId}-L${lotIndexPad}`;
  return {
    orderInternalId: internalOrderId,
    lotId: uniqueLotId,
    lotNumber: lot.lotNumber,
    quantity: lot.quantity,
    unit: lot.unit,
    calibrationDate: lot.calibrationDate,
    calibrationTime: lot.calibrationTime
  };
});

return [{
  json: {
    order: orderData,
    lotInserts
  }
}];

