const req = $input.first().json;
const headers = req.headers || {};
const query = req.query || {};

const authHeader = headers.authorization || headers.Authorization || query.token || '';
let token = authHeader.replace(/^Bearer /i, '').trim();

if (!token) {
  return [{ json: { error: true, statusCode: 401, message: 'Unauthorized access.' } }];
}

let decoded;
try {
  decoded = JSON.parse(Buffer.from(token, 'base64').toString('utf8'));
} catch(e) {
  return [{ json: { error: true, statusCode: 401, message: 'Invalid session.' } }];
}

return [{
  json: {
    userId: decoded.userId,
    clientId: decoded.clientId,
    role: decoded.role,
    fromDate: query.fromDate || null,
    toDate: query.toDate || null,
    status: query.status || null,
    productId: query.productId ? parseInt(query.productId, 10) : null,
    orderId: query.orderId ? query.orderId.trim() : null,
    page: parseInt(query.page || 1, 10),
    limit: Math.min(parseInt(query.limit || 50, 10), 100)
  }
}];

